export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-pos-0001", "section": "service", "who": "rubric", "text": "Мы приводим чин молебна Пресвятой Богородице (Малый молебный канон или «Параклисис»), который существует в виде самостоятельного законченного последования и служит образцом для всех прочих молебных пений."},
  {"id": "ru-pos-0002", "section": "service", "who": "deacon", "text": "Благослови, Владыка!"},
  {"id": "ru-pos-0003", "section": "service", "who": "priest", "text": "Благословен Бог наш всегда, ныне и присно, и во веки веков."},
  {"id": "ru-pos-0004", "section": "service", "who": "choir", "text": "Аминь. Царь Небесный:"},
  {"id": "ru-pos-0005", "section": "service", "who": "rubric", "text": "Чтец: Трисвятое."},
  {"id": "ru-pos-0006", "section": "service", "who": "choir", "text": "Слава, и ныне: Пресвятая Троица: Господи, помилуй. (3)"},
  {"id": "ru-pos-0007", "section": "service", "who": "choir", "text": "Слава, и ныне: Отче наш:"},
  {"id": "ru-pos-0008", "section": "service", "who": "priest", "text": "Ибо Твое есть Царство:"},
  {"id": "ru-pos-0009", "section": "service", "who": "reader", "text": "Аминь. Господи, помилуй. (12)"},
  {"id": "ru-pos-0010", "section": "service", "who": "reader", "text": "Слава, и ныне: Придите, поклонимся: (3)"},
  {"id": "ru-pos-0011", "section": "service", "who": "rubric", "text": "Псалом 142"},
  {"id": "ru-pos-0012", "section": "service", "who": "reader", "text": "Господи, услышь молитву мою, внемли молению моему в истине Твоей, услышь меня в правде Твоей и не войди в суд с рабом Твоим, ибо не оправдается пред Тобою никто из живущих. Ибо враг стал преследовать душу мою, унизил до земли жизнь мою, посадил меня во тьме, как умерших от века. И уныл во мне дух мой, во мне смутилось сердце моё. Вспомнил я дни древние, размыслил о всех делах Твоих, о творениях рук Твоих размышлял. Простёр к Тебе руки мои; душа моя пред Тобою – как безводная земля. Скоро услышь меня, Господи, изнемог дух мой: не отврати лица Твоего от меня, и да не уподоблюсь я сходящим в ров. Дай мне услышать рано утром милость Твою, ибо я на Тебя уповаю; открой мне, Господи, путь, по которому мне идти, ибо к Тебе вознёс я душу мою. Избавь меня от врагов моих, Господи, ибо к Тебе я прибег. Научи меня творить волю Твою, ибо Ты – Бог мой; Дух Твой благой поведёт меня в землю правды. Ради имени Твоего, Господи, Ты оживишь меня, по правде Твоей выведешь из печали душу мою, и по милости Твоей истребишь врагов моих, и погубишь всех теснящих душу мою, ибо я – раб Твой."},
  {"id": "ru-pos-0013", "section": "service", "who": "reader", "text": "Слава, и ныне: Аллилуия, аллилуия, аллилуия, слава Тебе, Боже. (3)"},
  {"id": "ru-pos-0014", "section": "service", "who": "rubric", "text": "Затем поем «Бог – Господь:» на глас тропаря, глас 4"},
  {"id": "ru-pos-0015", "section": "service", "who": "reader", "text": "Бог – Господь, и Он явился нам; благословен Грядущий во имя Господне. (4) Стих 1:"},
  {"id": "ru-pos-0016", "section": "service", "who": "reader", "text": "Прославляйте Господа, ибо Он благ, ибо вовек милость Его. Стих 2:"},
  {"id": "ru-pos-0017", "section": "service", "who": "reader", "text": "Обступив, окружили меня, но я именем Господним воспротивился им. Стих 3:"},
  {"id": "ru-pos-0018", "section": "service", "who": "reader", "text": "Не умру, но буду жить и возвещу дела Господни. Стих 4:"},
  {"id": "ru-pos-0019", "section": "service", "who": "reader", "text": "Камень, который отвергли строители, он оказался во главе угла: от Господа это было, и дивно в очах наших. Пс 117:27А, 26А, 1, 11, 17, 22–23"},
  {"id": "ru-pos-0020", "section": "service", "who": "rubric", "text": "И настоящие тропари, глас 4"},
  {"id": "ru-pos-0021", "section": "service", "who": "reader", "text": "К Богородице ныне усердно прибегнем / мы, грешные и смиренные, и к Ней припадем, / в покаянии взывая из глубины души: / «Владычица, помоги, над нами сжалившись, / поспеши, мы погибаем от множества согрешений! / Не отпусти Твоих рабов ни с чем: / ибо в Тебе имеем мы единственную надежду!» (Дважды)"},
  {"id": "ru-pos-0022", "section": "service", "who": "reader", "text": "Слава, и ныне: Не прекратим никогда, мы, недостойные, / возвещать о могуществе Твоем, Богородица, / ибо если бы Ты не защищала нас Своими молитвами, / кто бы нас избавил от стольких бед, / кто бы сохранил нас доныне свободными? / Не отступим, Владычица, от Тебя, / ибо Ты всегда спасаешь рабов Твоих от всяких бедствий. *"},
  {"id": "ru-pos-0023", "section": "service", "who": "rubric", "text": "* Или тропарь святому дважды,"},
  {"id": "ru-pos-0024", "section": "service", "who": "reader", "text": "Слава, и ныне,"},
  {"id": "ru-pos-0025", "section": "service", "who": "rubric", "text": "Богородичен того же гласа."},
  {"id": "ru-pos-0026", "section": "service", "who": "rubric", "text": "Псалом 50"},
  {"id": "ru-pos-0027", "section": "service", "who": "reader", "text": "Помилуй меня, Боже, по великой милости Твоей и по множеству щедрот Твоих изгладь беззаконие моё; совершенно омой меня от беззакония моего, и от греха моего очисти меня. Ибо беззаконие моё я знаю, и грех мой всегда предо мною. Тебе, Единому, я согрешил и злое пред Тобою сотворил, – да будешь оправдан в словах Твоих и победишь, если вступят с Тобою в суд. Ибо вот, я в беззакониях зачат, и во грехах родила меня мать моя. Ибо вот, Ты истину возлюбил, сокрытое и тайное премудрости Твоей мне открыл. Ты окропишь меня иссопом – и буду очищен; омоешь меня – и сделаюсь белее снега, дашь мне услышать радость и веселие – возрадуются кости униженные. Отврати лицо Твоё от грехов моих и все беззакония мои изгладь. Сердце чистое сотвори во мне, Боже, и Дух Правый обнови внутри меня. Не отринь меня от лица Твоего и Духа Твоего Святого не отними от меня. Возврати мне радость спасения Твоего и Духом Владычественным утверди меня. Научу беззаконных путям Твоим, и нечестивые к Тебе обратятся. Избавь меня от кровей, Боже, Боже спасения моего, возрадуется язык мой правде Твоей. Господи, Ты откроешь уста мои, и уста мои возвестят хвалу Твою. Ибо если бы жертвы Ты восхотел, я дал бы её, – к всесожжениям не будешь благоволить. Жертва Богу – дух сокрушённый, сердца сокрушённого и смиренного Бог не презрит. Облагодетельствуй, Господи, во благоволении Твоём Сион, и да будут воздвигнуты стены Иерусалима, – тогда примешь благосклонно жертву правды, возношение и всесожжения, тогда возложат на алтарь Твой тельцов."},
  {"id": "ru-pos-0028", "section": "service", "who": "rubric", "text": "Затем поем канон Пресвятой Богородице, без ирмосов. Творение Феостирикта монаха, глас 8. Песнь 1"},
  {"id": "ru-pos-0029", "section": "service", "who": "rubric", "text": "[Ирмос:"},
  {"id": "ru-pos-0030", "section": "service", "who": "reader", "text": "По воде пройдя, как по суше, / и египетского развращения избежав, / израильтянин взывал: / «Избавителю и Богу нашему воспоем!» ]*"},
  {"id": "ru-pos-0031", "section": "service", "who": "rubric", "text": "* Ирмосы по уставу не поются."},
  {"id": "ru-pos-0032", "section": "service", "who": "rubric", "text": "Припев:"},
  {"id": "ru-pos-0033", "section": "service", "who": "reader", "text": "Пресвятая Богородица, спаси нас. *"},
  {"id": "ru-pos-0034", "section": "service", "who": "rubric", "text": "* Припевы тому, кому поется канон."},
  {"id": "ru-pos-0035", "section": "service", "who": "reader", "text": "Множеством искушений томимый, / к Тебе прибегаю, спасения ища. / О Матерь Слова и Дева, / от бед и несчастий меня спаси! Припев:"},
  {"id": "ru-pos-0036", "section": "service", "who": "reader", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0037", "section": "service", "who": "reader", "text": "Страстей нападения меня смущают, / сильным унынием наполняя мою душу. / Умиротвори ее, Отроковица, тишиною / Сына Твоего и Бога, Всенепорочная."},
  {"id": "ru-pos-0038", "section": "service", "who": "reader", "text": "Слава: Тебя, родившую Спасителя и Бога, / умоляю об избавлении меня от бедствий; / ибо к Тебе, Дева, ныне прибегая, / простираю и душу, и помышление."},
  {"id": "ru-pos-0039", "section": "service", "who": "reader", "text": "И ныне: Меня, болящего телом и душою, / удостой божественного посещения / и попечения Твоего, единственная Богоматерь, / как благая и Благого Родительница."},
  {"id": "ru-pos-0040", "section": "service", "who": "rubric", "text": "Песнь 3"},
  {"id": "ru-pos-0041", "section": "service", "who": "rubric", "text": "[Ирмос:"},
  {"id": "ru-pos-0042", "section": "service", "who": "reader", "text": "Небесного свода Создатель, Господи, / и Церкви Строитель, / Ты меня утверди в любви к Тебе, / предел желаний, верных утверждение, / единый Человеколюбец. ] Припев:"},
  {"id": "ru-pos-0043", "section": "service", "who": "reader", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0044", "section": "service", "who": "reader", "text": "Защитою и покровом жизни моей / считаю я Тебя, Божия Родительница, Дева. / Ты меня направь, как кормчий, к пристани Твоей, / Виновница благ, верных утверждение, / одна всеми воспеваемая. Припев:"},
  {"id": "ru-pos-0045", "section": "service", "who": "reader", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0046", "section": "service", "who": "reader", "text": "Умоляю, Дева, смятение души / и бурю моего уныния рассеять, – / Ты, ведь, Божия Невеста, зачала / Начальника тишины Христа, / единая всечистая."},
  {"id": "ru-pos-0047", "section": "service", "who": "reader", "text": "Слава: Благодетеля родившая, благ Виновника, / благодеяния богатство всем источи, / ибо Ты всё можешь, / как мощного силою Христа родившая, / в Боге блаженная."},
  {"id": "ru-pos-0048", "section": "service", "who": "reader", "text": "И ныне: Тяжкими недугами / и болезненными страданиями испытуемому, / Ты, Дева, мне помоги, / ибо знаю я Тебя, Всенепорочная, как исцелений сокровищницу / неистощимую, неоскудевающую."},
  {"id": "ru-pos-0049", "section": "service", "who": "rubric", "text": "После 3-ой песни припевы"},
  {"id": "ru-pos-0050", "section": "service", "who": "rubric", "text": "Богородице:"},
  {"id": "ru-pos-0051", "section": "service", "who": "reader", "text": "Спаси от бед рабов Твоих, Богородица, / ибо все мы после Бога к Тебе прибегаем, / как к нерушимой Стене и Заступнице."},
  {"id": "ru-pos-0052", "section": "service", "who": "reader", "text": "Воззри благосклонно, Всехвальная Богородица, / на тяжкое тела моего страдание / и исцели души моей скорбь."},
  {"id": "ru-pos-0053", "section": "service", "who": "rubric", "text": "Или припевы Спасителю:"},
  {"id": "ru-pos-0054", "section": "service", "who": "reader", "text": "Избавь от бед рабов Твоих, Многомилостивый, / ибо мы усердно к Тебе прибегаем, / милостивому Избавителю, всех Владыке, / Господу Иисусу."},
  {"id": "ru-pos-0055", "section": "service", "who": "rubric", "text": "Или припевы святому:"},
  {"id": "ru-pos-0056", "section": "service", "who": "reader", "text": "Моли Бога о нас, (имя),"},
  {"id": "ru-pos-0057", "section": "service", "who": "reader", "text": "/ ибо мы усердно к Тебе прибегаем, / скорому помощнику и молитвеннику о душах наших."},
  {"id": "ru-pos-0058", "section": "service", "who": "rubric", "text": "Затем ектения сугубая, на которой поминаются те, за кого служится молебен"},
  {"id": "ru-pos-0059", "section": "service", "who": "deacon", "text": "Помилуй нас, Боже, по великой милости Твоей, молимся Тебе, услышь и помилуй."},
  {"id": "ru-pos-0060", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0061", "section": "service", "who": "choir", "text": "Ещё молимся о Великом Господине и отце нашем Святейшем Патриархе (имя)"},
  {"id": "ru-pos-0062", "section": "service", "who": "choir", "text": "и о господине нашем ("},
  {"id": "ru-pos-0063", "section": "service", "who": "choir", "text": "высоко )"},
  {"id": "ru-pos-0064", "section": "service", "who": "choir", "text": "преосвященнейшем митрополите (или:"},
  {"id": "ru-pos-0065", "section": "service", "who": "choir", "text": "архиепископе или:"},
  {"id": "ru-pos-0066", "section": "service", "who": "choir", "text": "епископе — имя)"},
  {"id": "ru-pos-0067", "section": "service", "who": "choir", "text": ", и о всём во Христе братстве нашем."},
  {"id": "ru-pos-0068", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0069", "section": "service", "who": "choir", "text": "Ещё молимся о Богохранимой стране нашей, властях и воинстве её, да тихую и безмятежную жизнь проведём во всяком благочестии и чистоте."},
  {"id": "ru-pos-0070", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0071", "section": "service", "who": "choir", "text": "Ещё молимся о милости, жизни, мире, здравии, спасении, посещении, прощении, благопоспешении рабов Божиих (имена)"},
  {"id": "ru-pos-0072", "section": "service", "who": "choir", "text": ", и о сохранении святого храма сего (или:"},
  {"id": "ru-pos-0073", "section": "service", "who": "choir", "text": "святой обители сей )"},
  {"id": "ru-pos-0074", "section": "service", "who": "choir", "text": "."},
  {"id": "ru-pos-0075", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0076", "section": "service", "who": "choir", "text": "Ещё молимся за всю братию и за всех христиан."},
  {"id": "ru-pos-0077", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0078", "section": "service", "who": "rubric", "text": "Священник возглашает:"},
  {"id": "ru-pos-0079", "section": "service", "who": "priest", "text": "Ибо Ты – милостивый и человеколюбивый Бог, и Тебе славу воссылаем, Отцу и Сыну и Святому Духу, ныне и всегда, и во веки веков."},
  {"id": "ru-pos-0080", "section": "service", "who": "choir", "text": "Аминь."},
  {"id": "ru-pos-0081", "section": "service", "who": "rubric", "text": "Тропарь, глас 2"},
  {"id": "ru-pos-0082", "section": "service", "who": "choir", "text": "Горячее Ходатайство и Стена неприступная, / милости Источник, мiру Прибежище! / Мы усердно взываем к Тебе: / «Богородица Владычица, поспеши / и от бед избавь нас, / единственная скорая Заступница!» *"},
  {"id": "ru-pos-0083", "section": "service", "who": "rubric", "text": "* Или седален святому, которому служим молебен."},
  {"id": "ru-pos-0084", "section": "service", "who": "rubric", "text": "Песнь 4"},
  {"id": "ru-pos-0085", "section": "service", "who": "rubric", "text": "[Ирмос:"},
  {"id": "ru-pos-0086", "section": "service", "who": "choir", "text": "Услышал я, Господи, / о таинстве Твоего промысла, / уразумел дела Твои, / и прославил Твоё Божество. ] Припев:"},
  {"id": "ru-pos-0087", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0088", "section": "service", "who": "choir", "text": "Успокой страстей моих волнение, / Кормчего – Господа родившая, / и бурю моих согрешений, / Божия Невеста. Припев:"},
  {"id": "ru-pos-0089", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0090", "section": "service", "who": "choir", "text": "Милосердия Твоего подай бездну / мне, о помощи взывающему, / Милосердного Родившая / и Спасителя всех, воспевающих Тебя. Припев:"},
  {"id": "ru-pos-0091", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0092", "section": "service", "who": "choir", "text": "Наслаждаясь, Всечистая, / Твоими дарами, / мы воспеваем благодарственную песнь, / зная Тебя, Богоматерь."},
  {"id": "ru-pos-0093", "section": "service", "who": "choir", "text": "Слава: ("},
  {"id": "ru-pos-0094", "section": "service", "who": "choir", "text": "На одре болезни моей / и немощи лежащему, / помоги мне, Богородица, как любящая добро, / единственная вечно девственная. )"},
  {"id": "ru-pos-0095", "section": "service", "who": "choir", "text": "И ныне: Как надежду, и утверждение, / и спасения стену непоколебимую, / имея Тебя, всепрославленная, / мы от всякого затруднения избавляемся."},
  {"id": "ru-pos-0096", "section": "service", "who": "rubric", "text": "Песнь 5"},
  {"id": "ru-pos-0097", "section": "service", "who": "rubric", "text": "[Ирмос:"},
  {"id": "ru-pos-0098", "section": "service", "who": "choir", "text": "Просвети нас повелениями Твоими, Господи, / и рукою Твоею вознесенною / Твой мир подай нам, Человеколюбец. ] Припев:"},
  {"id": "ru-pos-0099", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0100", "section": "service", "who": "choir", "text": "Исполни, Чистая, весельем сердце моё, / Твою неомраченную давая радость, / родившая веселья Виновника. Припев:"},
  {"id": "ru-pos-0101", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0102", "section": "service", "who": "choir", "text": "Избавь нас от бед, Богородица чистая, / родившая вечное избавление / и мир, всякий ум превосходящий."},
  {"id": "ru-pos-0103", "section": "service", "who": "choir", "text": "Слава: Рассей согрешений моих мглу, / Божия Невеста, / светом Твоего сияния, / Свет родившая божественный и предвечный."},
  {"id": "ru-pos-0104", "section": "service", "who": "choir", "text": "И ныне: Исцели, Чистая, души моей немощь, / удостоив Твоего посещения, / и здравие ходатайством Твоим подай мне."},
  {"id": "ru-pos-0105", "section": "service", "who": "rubric", "text": "Песнь 6"},
  {"id": "ru-pos-0106", "section": "service", "who": "rubric", "text": "[Ирмос:"},
  {"id": "ru-pos-0107", "section": "service", "who": "choir", "text": "Я пролью молитву к Господу / и Ему возвещу печали мои, / ибо зол душа моя преисполнилась / и жизнь моя ко аду приблизилась, / и молюсь я, как Иона: / «От погибели, Боже, изведи меня!» ] Припев:"},
  {"id": "ru-pos-0108", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0109", "section": "service", "who": "choir", "text": "Того, Кто спас от смерти и тления, / Самого Себя предав на смерть, / естество моё, смертью и тлением объятое, / – Господа и Сына Твоего, – Дева, умоли / от злодейства врагов меня избавить. Припев:"},
  {"id": "ru-pos-0110", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0111", "section": "service", "who": "choir", "text": "Как Защитницу жизни я знаю Тебя, / и охрану вернейшую, Дева, / и рассеивающую искушений множество, / и злобу демонов прогоняющую, / и молю Тебя всегда / от пагубных страстей моих избавить меня."},
  {"id": "ru-pos-0112", "section": "service", "who": "choir", "text": "Слава: Мы Тебя как стену убежища имеем, / и душ всецелое спасение, / и простор в скорбях, Отроковица, / и во свете Твоём ликуем всегда. / И ныне нас, о Владычица, / от страстей и бед спаси."},
  {"id": "ru-pos-0113", "section": "service", "who": "choir", "text": "И ныне: На одре ныне в немощи лежу, / и нет исцеления плоти моей; / но Бога, и Спасителя мiра, / и Избавителя от недугов родившая, / Тебя, благую, молю: / от гибельных болезней (меня) воздвигни!"},
  {"id": "ru-pos-0114", "section": "service", "who": "rubric", "text": "После 6-ой песни повторяем припевы"},
  {"id": "ru-pos-0115", "section": "service", "who": "rubric", "text": "Припевы Богородице:"},
  {"id": "ru-pos-0116", "section": "service", "who": "choir", "text": "Спаси от бед рабов Твоих, Богородица, / ибо все мы после Бога к Тебе прибегаем, / как к нерушимой Стене и Заступнице."},
  {"id": "ru-pos-0117", "section": "service", "who": "choir", "text": "Воззри благосклонно, Всехвальная Богородица, / на тяжкое тела моего страдание / и исцели души моей скорбь."},
  {"id": "ru-pos-0118", "section": "service", "who": "rubric", "text": "Затем ектения сугубая"},
  {"id": "ru-pos-0119", "section": "service", "who": "deacon", "text": "Помилуй нас, Боже, по великой милости Твоей, молимся Тебе, услышь и помилуй."},
  {"id": "ru-pos-0120", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0121", "section": "service", "who": "choir", "text": "Ещё молимся о Великом Господине и отце нашем Святейшем Патриархе (имя)"},
  {"id": "ru-pos-0122", "section": "service", "who": "choir", "text": "и о господине нашем ("},
  {"id": "ru-pos-0123", "section": "service", "who": "choir", "text": "высоко )"},
  {"id": "ru-pos-0124", "section": "service", "who": "choir", "text": "преосвященнейшем митрополите (или:"},
  {"id": "ru-pos-0125", "section": "service", "who": "choir", "text": "архиепископе или:"},
  {"id": "ru-pos-0126", "section": "service", "who": "choir", "text": "епископе — имя)"},
  {"id": "ru-pos-0127", "section": "service", "who": "choir", "text": ", и о всём во Христе братстве нашем."},
  {"id": "ru-pos-0128", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0129", "section": "service", "who": "choir", "text": "Ещё молимся о Богохранимой стране нашей, властях и воинстве её, да тихую и безмятежную жизнь проведём во всяком благочестии и чистоте."},
  {"id": "ru-pos-0130", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0131", "section": "service", "who": "choir", "text": "Ещё молимся о милости, жизни, мире, здравии, спасении, посещении, прощении, благопоспешении рабов Божиих (имена)"},
  {"id": "ru-pos-0132", "section": "service", "who": "choir", "text": ", и о сохранении святого храма сего (или:"},
  {"id": "ru-pos-0133", "section": "service", "who": "choir", "text": "святой обители сей )"},
  {"id": "ru-pos-0134", "section": "service", "who": "choir", "text": "."},
  {"id": "ru-pos-0135", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0136", "section": "service", "who": "choir", "text": "Ещё молимся за всю братию и за всех христиан."},
  {"id": "ru-pos-0137", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0138", "section": "service", "who": "rubric", "text": "Священник возглашает:"},
  {"id": "ru-pos-0139", "section": "service", "who": "priest", "text": "Ибо Ты – милостивый и человеколюбивый Бог, и Тебе славу воссылаем, Отцу и Сыну и Святому Духу, ныне и всегда, и во веки веков."},
  {"id": "ru-pos-0140", "section": "service", "who": "choir", "text": "Аминь."},
  {"id": "ru-pos-0141", "section": "service", "who": "rubric", "text": "Кондак, глас 6"},
  {"id": "ru-pos-0142", "section": "service", "who": "choir", "text": "Защита христиан надежная, / Ходатайство ко Творцу неизменное! / Молитвенных голосов грешников не презри, / но скоро приди, как Благая, на помощь нам, / с верою взывающим Тебе: / «Поспеши с заступлением и ускорь моление, Богородица, / всегда защищая чтущих Тебя!» *"},
  {"id": "ru-pos-0143", "section": "service", "who": "rubric", "text": "* Или кондак святому."},
  {"id": "ru-pos-0144", "section": "service", "who": "rubric", "text": "[По греческому уставу далее поется Степенный антифон 4 гласа"},
  {"id": "ru-pos-0145", "section": "service", "who": "choir", "text": "«С юности моей:» ]"},
  {"id": "ru-pos-0146", "section": "service", "who": "deacon", "text": "Будем внимать."},
  {"id": "ru-pos-0147", "section": "service", "who": "priest", "text": "Мир всем."},
  {"id": "ru-pos-0148", "section": "service", "who": "choir", "text": "И духу твоему."},
  {"id": "ru-pos-0149", "section": "service", "who": "deacon", "text": "Премудрость."},
  {"id": "ru-pos-0150", "section": "service", "who": "rubric", "text": "Прокимен, глас 4"},
  {"id": "ru-pos-0151", "section": "service", "who": "deacon", "text": "Памятным сделаю имя Твоё / во всяком роде и роде. Стих:"},
  {"id": "ru-pos-0152", "section": "service", "who": "deacon", "text": "Услышь, Дочь, и посмотри, и склони ухо Твоё. *"},
  {"id": "ru-pos-0153", "section": "service", "who": "deacon", "text": "Пс 44:18А, 11А"},
  {"id": "ru-pos-0154", "section": "service", "who": "rubric", "text": "* Или прокимен святому."},
  {"id": "ru-pos-0155", "section": "service", "who": "deacon", "text": "Господу помолимся."},
  {"id": "ru-pos-0156", "section": "service", "who": "choir", "text": "Господи, помилуй."},
  {"id": "ru-pos-0157", "section": "service", "who": "rubric", "text": "Священник возглашает:"},
  {"id": "ru-pos-0158", "section": "service", "who": "priest", "text": "Ибо свят Ты, Боже наш, и во святых почиваешь, и Тебе славу воссылаем, Отцу и Сыну и Святому Духу, ныне и всегда, и во веки веков."},
  {"id": "ru-pos-0159", "section": "service", "who": "choir", "text": "Аминь."},
  {"id": "ru-pos-0160", "section": "service", "who": "rubric", "text": "Диакон возглашает второй прокимен"},
  {"id": "ru-pos-0161", "section": "service", "who": "choir", "text": "Всё, что дышит, / да восхвалит Господа. Стих:"},
  {"id": "ru-pos-0162", "section": "service", "who": "choir", "text": "Хвалите Бога во святых Его, хвалите Его на тверди силы Его. Пс 150:6, 1"},
  {"id": "ru-pos-0163", "section": "service", "who": "deacon", "text": "Дабы удостоиться нам услышать святое Евангелие, Господа Бога молим."},
  {"id": "ru-pos-0164", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0165", "section": "service", "who": "deacon", "text": "Премудрость! Станем благоговейно. Услышим святое Евангелие."},
  {"id": "ru-pos-0166", "section": "service", "who": "priest", "text": "Мир всем."},
  {"id": "ru-pos-0167", "section": "service", "who": "choir", "text": "И духу твоему."},
  {"id": "ru-pos-0168", "section": "service", "who": "priest", "text": "От Луки святого Евангелия чтение."},
  {"id": "ru-pos-0169", "section": "service", "who": "choir", "text": "Слава Тебе, Господи, слава Тебе."},
  {"id": "ru-pos-0170", "section": "service", "who": "deacon", "text": "Будем внимать."},
  {"id": "ru-pos-0171", "section": "service", "who": "rubric", "text": "Евангелие от Луки, зачало 4"},
  {"id": "ru-pos-0172", "section": "service", "who": "deacon", "text": "В те дни Мариам, встав, пошла с поспешностью в горную страну, в город Иудин, и вошла в дом Захарии и приветствовала Елисавету. И было: когда услышала Елисавета приветствие Марии, взыграл младенец во чреве ее; и исполнилась Духа Святого Елисавета, и воскликнула громким голосом, и сказала: «Благословенна Ты между женами, и благословен Плод чрева Твоего! И откуда это мне, что пришла Матерь Господа моего ко мне? Ибо вот, когда прозвучал глас приветствия Твоего в ушах моих, взыграл младенец от радости во чреве моем; и блаженна Уверовавшая, что совершится сказанное Ей от Господа». И сказала Мариам: «Величает душа Моя Господа, и возрадовался дух Мой о Боге, Спасителе Моем, что призрел Он на смирение рабы Своей; ибо вот, отныне будут называть Меня блаженной все роды; что сотворил Мне великое Сильный, и свято имя Его». Пробыла же Мариам с нею около трех месяцев и возвратилась в дом Свой. *"},
  {"id": "ru-pos-0173", "section": "service", "who": "deacon", "text": "Лк 1:39–49, 56"},
  {"id": "ru-pos-0174", "section": "service", "who": "rubric", "text": "* Или Евангелие святому, читающиеся на Утрени."},
  {"id": "ru-pos-0175", "section": "service", "who": "choir", "text": "Слава Тебе, Господи, слава Тебе!"},
  {"id": "ru-pos-0176", "section": "service", "who": "rubric", "text": "Глас 6"},
  {"id": "ru-pos-0177", "section": "service", "who": "choir", "text": "Слава: По молитвам Богородицы, / Милостивый, изгладь / множество согрешений наших. *"},
  {"id": "ru-pos-0178", "section": "service", "who": "rubric", "text": "* На молебне святому:"},
  {"id": "ru-pos-0179", "section": "service", "who": "choir", "text": "По молитвам святого ( имя)"},
  {"id": "ru-pos-0180", "section": "service", "who": "choir", "text": ", / Милостивый:"},
  {"id": "ru-pos-0181", "section": "service", "who": "choir", "text": "И ныне: По молитвам Богородицы, / Милостивый, изгладь / множество согрешений наших."},
  {"id": "ru-pos-0182", "section": "service", "who": "choir", "text": "Помилуй меня, Боже, / по великой милости Твоей / и по множеству щедрот Твоих / изгладь беззаконие моё."},
  {"id": "ru-pos-0183", "section": "service", "who": "rubric", "text": "Стихира, глас 6"},
  {"id": "ru-pos-0184", "section": "service", "who": "choir", "text": "Не вверяй меня человеческому заступлению, / Пресвятая Владычица, / но прими моление раба Твоего: / ибо скорбь объяла меня, / не могу выносить стрел, демонами пущенных; / защиты нет у меня / и некуда прибегнуть мне несчастному, / со всех сторон боримому / и не имеющего утешения, кроме Тебя. / Владычица мiра, надежда и Заступница верных, / не презри моления моего, полезное мне сотвори! *"},
  {"id": "ru-pos-0185", "section": "service", "who": "rubric", "text": "* Или стихира святому."},
  {"id": "ru-pos-0186", "section": "service", "who": "priest", "text": "Спаси, Боже, народ Твой и благослови наследие Твоё, посети мир Твой милостью и щедротами, возвысь рог христиан православных и ниспошли на нас богатые Твои милости: по ходатайствам всечистой Владычицы нашей Богородицы и Приснодевы Марии, силою священного и животворящего Креста; заступлением святых небесных Сил бесплотных, [мольбами] святого славного пророка Предтечи и Крестителя Иоанна, святых славных и всехвальных Апостолов; святых отцов наших, [великих] иерархов и вселенских учителей Василия Великого, Григория Богослова и Иоанна Златоуста; святого отца нашего Николая, архиепископа Мир Ликийских, чудотворца; святых равноапостольных Мефодия и Кирилла, учителей славянских, святых равноапостольных великого князя Владимира и великой княгини Ольги; святых отцов наших и всероссийских чудотворцев Петра, Алексия, Ионы, Филиппа и Ермогена; святых славных и победоносных мучеников, преподобных и богоносных отцов наших, святых и праведных богоотцов Иоакима и Анны, (святого храма и святых дня)"},
  {"id": "ru-pos-0187", "section": "service", "who": "priest", "text": "и всех Твоих святых: умоляем Тебя, многомилостивый Господи, услышь нас, грешных, молящихся Тебе, и помилуй нас."},
  {"id": "ru-pos-0188", "section": "service", "who": "choir", "text": "Господи, помилуй. (12)"},
  {"id": "ru-pos-0189", "section": "service", "who": "rubric", "text": "Священник возглашает:"},
  {"id": "ru-pos-0190", "section": "service", "who": "priest", "text": "По милости и щедротам и человеколюбию единородного Твоего Сына, с Которым благословен Ты, со всесвятым и благим и животворящим Твоим Духом, ныне и всегда и во веки веков."},
  {"id": "ru-pos-0191", "section": "service", "who": "choir", "text": "Аминь."},
  {"id": "ru-pos-0192", "section": "service", "who": "rubric", "text": "Песнь 7"},
  {"id": "ru-pos-0193", "section": "service", "who": "rubric", "text": "[Ирмос:"},
  {"id": "ru-pos-0194", "section": "service", "who": "choir", "text": "Из Иудеи пришедшие юноши / в Вавилоне некогда / верою в Троицу попрали пламя печи, воспевая: / «Боже отцов наших, благословен Ты!» ] Припев:"},
  {"id": "ru-pos-0195", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0196", "section": "service", "who": "choir", "text": "Наше спасение восхотев устроить, / Ты, Спаситель, вселился во чрево Девы, / Которую Защитницей мiра явил. / Боже отцов наших, благословен Ты! Припев:"},
  {"id": "ru-pos-0197", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0198", "section": "service", "who": "choir", "text": "Любящего милосердие, / рожденного Тобою, Матерь чистая, / умоли, да избавимся от согрешений / и душевных скверн / мы, с верою взывающие: / «Боже отцов наших, благословен Ты!»"},
  {"id": "ru-pos-0199", "section": "service", "who": "choir", "text": "Слава: Сокровищницей спасения / и источником бессмертия / явил Ты Тебя Родившую, / и твердыней безопасной, / и дверью покаяния для взывающих: / «Боже отцов наших, благословен Ты!»"},
  {"id": "ru-pos-0200", "section": "service", "who": "choir", "text": "И ныне: Телесные немощи / и душевные недуги, Божия Родительница, / с любовью приходящих / к покрову Твоему божественному, / исцелить благоволи, / Спасителя Христа нам родившая."},
  {"id": "ru-pos-0201", "section": "service", "who": "rubric", "text": "Песнь 8"},
  {"id": "ru-pos-0202", "section": "service", "who": "rubric", "text": "[Ирмос:"},
  {"id": "ru-pos-0203", "section": "service", "who": "choir", "text": "Царя небесного, / Которого воспевают воинства Ангелов, / воспевайте и превозносите / во все века. ] Припев:"},
  {"id": "ru-pos-0204", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0205", "section": "service", "who": "choir", "text": "Помощи у Тебя просящих / не презри, Дева / поющих Тебя, Отроковица, / и превозносящих вовеки. Припев:"},
  {"id": "ru-pos-0206", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0207", "section": "service", "who": "choir", "text": "Немощи души моей Ты врачуешь, / и телесные страдания, Дева, / чтобы я прославлял Тебя, / благодатную, (вовеки)."},
  {"id": "ru-pos-0208", "section": "service", "who": "choir", "text": "Слава: Исцеления Ты обильно изливаешь / с верою воспевающим Тебя, Дева, / и превозносящих непостижимое / рождение Тобою Христа."},
  {"id": "ru-pos-0209", "section": "service", "who": "choir", "text": "И ныне: Искушений приступы Ты отражаешь / и страстей нападения, Дева, / потому мы воспеваем / Тебя во все века."},
  {"id": "ru-pos-0210", "section": "service", "who": "rubric", "text": "Песнь 9"},
  {"id": "ru-pos-0211", "section": "service", "who": "rubric", "text": "[Ирмос:"},
  {"id": "ru-pos-0212", "section": "service", "who": "choir", "text": "Истинно Богородицей Тебя исповедуем / мы, спасенные Тобою, Дева чистая, / с сонмами бесплотных Тебя величая. ] Припев:"},
  {"id": "ru-pos-0213", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0214", "section": "service", "who": "choir", "text": "Слез моих потока не отвергни, / Дева, родившая Христа, / со всякого лица всякую слезу отершего. Припев:"},
  {"id": "ru-pos-0215", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0216", "section": "service", "who": "choir", "text": "Радостью моё сердце исполни, Дева, / радости полноту принявшая, / печаль же греха истребившая. Припев:"},
  {"id": "ru-pos-0217", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0218", "section": "service", "who": "choir", "text": "Пристанищем и защитой соделайся, / к Тебе прибегающим, Дева, / и стеною непоколебимой, / и убежищем, и покровом, и радостью."},
  {"id": "ru-pos-0219", "section": "service", "who": "choir", "text": "Слава: Света Твоего лучами озари, Дева, / мрак неведения прогоняя, / благоговейно Богородицей / Тебя исповедующих."},
  {"id": "ru-pos-0220", "section": "service", "who": "choir", "text": "И ныне: На месте страдания от болезни / смирившегося, Дева, исцели, / из немощи во здравие претворяя."},
  {"id": "ru-pos-0221", "section": "service", "who": "rubric", "text": "По окончании канона поем"},
  {"id": "ru-pos-0222", "section": "service", "who": "choir", "text": "Достойно есть воистину / прославлять Тебя, Богородицу, / вечно блаженную и пренепорочную / и Матерь Бога нашего. / Честью высшую Херувимов / и несравненно славнейшую Серафимов, / девственно Бога-Слово родившую, / истинную Богородицу – Тебя величаем."},
  {"id": "ru-pos-0223", "section": "service", "who": "rubric", "text": "И если служим молебен Богородице, то поем настоящие припевы, во время пения которых священник кадит храм:"},
  {"id": "ru-pos-0224", "section": "service", "who": "rubric", "text": "Припевы Богородице"},
  {"id": "ru-pos-0225", "section": "service", "who": "priest", "text": "Высочайшую небес / и чистейшую сияний солнечных, / избавившую нас от проклятия / Владычицу мiра / песнопениями почтим."},
  {"id": "ru-pos-0226", "section": "service", "who": "priest", "text": "От многих грехов / в немощи мое тело / немощна и душа моя. / К Тебе прибегаю, Благодатной: / Надежда безнадежных, / Ты мне помоги!"},
  {"id": "ru-pos-0227", "section": "service", "who": "priest", "text": "Владычица и Матерь Искупителя! / Прими прошения / недостойных рабов Твоих / о Твоем перед Рожденным от Тебя за нас ходатайстве. / О Владычица мiра, стань между нами Посредницей!"},
  {"id": "ru-pos-0228", "section": "service", "who": "priest", "text": "Поем усердно ныне песнь / Тебе, всехвальной Богородице, радостно: / с Предтечей и всеми святыми / моли, Богородица, / о милости к нам."},
  {"id": "ru-pos-0229", "section": "service", "who": "priest", "text": "[Безмолвны да будут уста нечестивых, / не поклоняющихся чтимой иконе Твоей, / написанной Апостолом Лукой священнейшим, / Одигитрии.]"},
  {"id": "ru-pos-0230", "section": "service", "who": "priest", "text": "Все Ангелов воинства, / Предтеча Господень, / двенадцать Апостолов, святые все / с Богородицею сотворите ходатайство / о спасении нашем! Трисвятое."},
  {"id": "ru-pos-0231", "section": "service", "who": "priest", "text": "Слава, и ныне: Пресвятая Троица: Господи, помилуй. (3)"},
  {"id": "ru-pos-0232", "section": "service", "who": "priest", "text": "Слава, и ныне: Отче наш:"},
  {"id": "ru-pos-0233", "section": "service", "who": "priest", "text": "Ибо Твое есть Царство:"},
  {"id": "ru-pos-0234", "section": "service", "who": "reader", "text": "Аминь."},
  {"id": "ru-pos-0235", "section": "service", "who": "rubric", "text": "Тропари, глас 6*"},
  {"id": "ru-pos-0236", "section": "service", "who": "reader", "text": "Помилуй нас, Господи, помилуй нас, / ибо, не находя себе никакого оправдания, / молитву эту мы, грешные, Тебе приносим, как Владыке: / «Помилуй нас!»"},
  {"id": "ru-pos-0237", "section": "service", "who": "reader", "text": "Слава: Господи, помилуй нас, ибо на Тебя мы уповаем, / не прогневайся на нас сильно / и не вспомни беззаконий наших, / но воззри и ныне, как Милосердный / и избавь нас от врагов наших. / Ибо Ты – Бог наш, и мы – Твой народ; / все мы – дело рук Твоих / и имя Твоё призываем."},
  {"id": "ru-pos-0238", "section": "service", "who": "reader", "text": "И ныне: Милосердия двери отверзи нам, / благословенная Богородица, / дабы мы, надеясь на Тебя, не постыдились, / но избавились молитвами Твоими от бед, / ибо Ты – спасение рода христианского."},
  {"id": "ru-pos-0239", "section": "service", "who": "rubric", "text": "* Или тропарь святому (1) Слава, и ныне: Богородичен."},
  {"id": "ru-pos-0240", "section": "service", "who": "rubric", "text": "Затем ектения сугубая"},
  {"id": "ru-pos-0241", "section": "service", "who": "deacon", "text": "Помилуй нас, Боже, по великой милости Твоей, молимся Тебе, услышь и помилуй."},
  {"id": "ru-pos-0242", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0243", "section": "service", "who": "choir", "text": "Ещё молимся о Великом Господине и отце нашем Святейшем Патриархе (имя)"},
  {"id": "ru-pos-0244", "section": "service", "who": "choir", "text": "и о господине нашем ("},
  {"id": "ru-pos-0245", "section": "service", "who": "choir", "text": "высоко )"},
  {"id": "ru-pos-0246", "section": "service", "who": "choir", "text": "преосвященнейшем митрополите (или:"},
  {"id": "ru-pos-0247", "section": "service", "who": "choir", "text": "архиепископе или:"},
  {"id": "ru-pos-0248", "section": "service", "who": "choir", "text": "епископе — имя)"},
  {"id": "ru-pos-0249", "section": "service", "who": "choir", "text": ", и о всём во Христе братстве нашем."},
  {"id": "ru-pos-0250", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0251", "section": "service", "who": "choir", "text": "Ещё молимся о Богохранимой стране нашей, властях и воинстве её, да тихую и безмятежную жизнь проведём во всяком благочестии и чистоте."},
  {"id": "ru-pos-0252", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0253", "section": "service", "who": "choir", "text": "Ещё молимся о милости, жизни, мире, здравии, спасении, посещении, прощении, благопоспешении рабов Божиих (имена)"},
  {"id": "ru-pos-0254", "section": "service", "who": "choir", "text": ", и о сохранении святого храма сего (или:"},
  {"id": "ru-pos-0255", "section": "service", "who": "choir", "text": "святой обители сей )"},
  {"id": "ru-pos-0256", "section": "service", "who": "choir", "text": "."},
  {"id": "ru-pos-0257", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0258", "section": "service", "who": "choir", "text": "Ещё молимся за всю братию и за всех христиан."},
  {"id": "ru-pos-0259", "section": "service", "who": "choir", "text": "Господи, помилуй. (3)"},
  {"id": "ru-pos-0260", "section": "service", "who": "rubric", "text": "Священник возглашает:"},
  {"id": "ru-pos-0261", "section": "service", "who": "priest", "text": "Ибо Ты – милостивый и человеколюбивый Бог, и Тебе славу воссылаем, Отцу и Сыну и Святому Духу, ныне и всегда, и во веки веков."},
  {"id": "ru-pos-0262", "section": "service", "who": "choir", "text": "Аминь."},
  {"id": "ru-pos-0263", "section": "service", "who": "rubric", "text": "И читаем молитву, кому служится молебен."},
  {"id": "ru-pos-0264", "section": "service", "who": "rubric", "text": "Если служим молебен Пресвятой Богородице, священник возглашает:"},
  {"id": "ru-pos-0265", "section": "service", "who": "priest", "text": "Пресвятой Владычице, Деве Богородице помолимся."},
  {"id": "ru-pos-0266", "section": "service", "who": "choir", "text": "Пресвятая Богородица, спаси нас."},
  {"id": "ru-pos-0267", "section": "service", "who": "rubric", "text": "Молитва Пресвятой Богородице"},
  {"id": "ru-pos-0268", "section": "service", "who": "choir", "text": "О, Пресвятая Госпожа, Владычица Богородица! Ты выше всех Ангелов и Архангелов и почитаема более всего сотворенного: Помощница обижаемых, надежда потерявших надежду, нищих Заступница, печальных утешение, алчущих Питательница, нагих одеяние, больных исцеление, грешных спасение, всем христианам помощь и защита. О, всемилостивая Госпожа, Дева Богородица Владычица! Милостию твоею спаси и помилуй рабов твоих, святейших патриархов православных, и преосвященнейших митрополитов, архиепископов и епископов, и весь священнический и иноческий чин. Спаси, Госпожа, и помилуй богохранимую страну нашу Российскую, народ ее и всех стоящих у власти, военачальников, градоначальников и все воинство, и делающих добро, и всех православных христиан ризою твоею священной защити. И умоли, Госпожа, из Тебя без семени воплотившегося Христа, Бога нашего, да препояшет нас силою своею свыше против невидимых и видимых врагов наших. О, всемилостивая Госпожа, Владычица Богородица! Воздвигни нас из глубины греха и избавь нас от голода, мора, от землетрясения и потопа, от огня и меча, от нашествия иноплеменников и междоусобной войны, и от внезапной смерти, и от нападения врага, и от пагубных ветров, и от смертоносной язвы, и от всякого зла. Подай, Госпожа, мир и здравие рабам твоим, всем православным христианам, и просвети им ум и очи сердца для их спасения, и удостой нас, грешных рабов твоих, Царства Сына Твоего, Христа Бога нашего. Ибо владычество Его благословенно и прославлено, со безначальным Его Отцом и всесвятым, и благим, и животворящим Его Духом, ныне, и всегда, и во веки веков. Аминь."},
  {"id": "ru-pos-0269", "section": "service", "who": "rubric", "text": "Молитва иная"},
  {"id": "ru-pos-0270", "section": "service", "who": "choir", "text": "Царица моя преблагая, Надежда моя, Богородица, приют сирот и странников защитница, скорбящих радость, обиженных покровительница! Видишь мою беду, видишь мою скорбь; помоги мне, как немощному, направь меня, как странника. Обиду мою знаешь: разреши ее по Своей воле. Ибо не имею я иной помощи, кроме Тебя, ни иной Защитницы, ни благой Утешительницы – только Тебя, о Богоматерь: да сохранишь меня и защитишь во веки веков. Аминь."},
  {"id": "ru-pos-0271", "section": "service", "who": "rubric", "text": "Молитва иная"},
  {"id": "ru-pos-0272", "section": "service", "who": "choir", "text": "К кому воззову, Владычица? К кому прибегну в горести моей, если не к Тебе, Царица небесная? Кто плач мой и воздыхание мое благосклонно примет, если не Ты, Пренепорочная, надежда христиан и прибежище нам, грешным? Кто лучше Тебя в напастях защитит? Услышь же стенание мое и приклони ухо Твое ко мне, Владычица, Матерь Бога моего; и не презри меня, нуждающегося в Твоей помощи, и не отринь меня, грешного. Вразуми и научи меня, Царица Небесная; не отступи от меня, раба Твоего, Владычица, за ропот мой, но будь мне Матерью и Заступницей. Вручаю себя милостивому покровительству Твоему: приведи меня, грешного, к тихой и безмятежной жизни, дабы я плакал о грехах моих. Ибо к кому прибегну я, виновный, если не к Тебе, упованию и прибежищу грешных, надеждою на неизреченную милость Твою и щедроты Твои окрыляясь? О Владычица, Царица Небесная! Ты мне упование и прибежище, покров и заступление, и помощь. Царица моя преблагая и скорая Заступница! Покрой Твоим ходатайством мои согрешения, защити меня от врагов видимых и невидимых; смягчи сердца злых людей, восстающих на меня. О Матерь Господа, моего Творца! Ты – корень девства и неувядаемый цвет чистоты. О Божия Родительница! Ты подай мне помощь, немощному от плотских страстей и болезнующему сердцем, ибо имею я одну Твою и с Тобою Сына Твоего защиту; и да избавлюсь я Твоим пречудным заступлением от всякой беды и напасти, о пренепорочная и преславная Божия Матерь Мария. Потому с надеждою возглашаю и взываю: «Радуйся, Благодатная! Радуйся обрадованная! Радуйся, преблагословенная, Господь с Тобою!» ]*"},
  {"id": "ru-pos-0273", "section": "service", "who": "rubric", "text": "* Молитва читается одна, какую изволит настоятель. По традиции после неё, во время целования иконы, может быть пропето величание."},
  {"id": "ru-pos-0274", "section": "service", "who": "rubric", "text": "Величание"},
  {"id": "ru-pos-0275", "section": "service", "who": "choir", "text": "Величаем Тебя, / Пресвятая Дева, / Богом избранная Отроковица / и чтим образ Твой святой: / им Ты источаешь исцеления / всем с верою к Тебе прибегающим. *"},
  {"id": "ru-pos-0276", "section": "service", "who": "rubric", "text": "* Или величание святому."},
  {"id": "ru-pos-0277", "section": "service", "who": "deacon", "text": "Премудрость."},
  {"id": "ru-pos-0278", "section": "service", "who": "priest", "text": "Пресвятая Богородица, спаси нас!"},
  {"id": "ru-pos-0279", "section": "service", "who": "choir", "text": "Честью высшую Херувимов / и несравненно славнейшую Серафимов, / девственно Бога-Слово родившую, / истинную Богородицу – Тебя величаем."},
  {"id": "ru-pos-0280", "section": "service", "who": "priest", "text": "Слава Тебе, Христе Боже, Надежда наша, слава Тебе."},
  {"id": "ru-pos-0281", "section": "service", "who": "choir", "text": "Слава, и ныне, Господи, помилуй. (3)"},
  {"id": "ru-pos-0282", "section": "service", "who": "choir", "text": "Благослови."},
  {"id": "ru-pos-0283", "section": "service", "who": "rubric", "text": "Священник произносит отпуст"},
  {"id": "ru-pos-0284", "section": "service", "who": "choir", "text": "(Воскресший из мёртвых,) Христос, истинный Бог наш, по молитвам Пречистой Своей Матери, святых славных и всехвальных апостолов, (святых храма и"},
  {"id": "ru-pos-0285", "section": "service", "who": "rubric", "text": "дня – имена их)"},
  {"id": "ru-pos-0286", "section": "service", "who": "choir", "text": ", святых и праведных богоотцов Иоакима и Анны и всех святых, помилует и спасёт нас, как Благой и Человеколюбец."},
  {"id": "ru-pos-0287", "section": "service", "who": "choir", "text": "Аминь."},
  {"id": "ru-pos-0288", "section": "service", "who": "rubric", "text": "[Затем, пока присутствующие целуют икону Пресвятой Богородицы поются следующие тропари:"},
  {"id": "ru-pos-0289", "section": "service", "who": "rubric", "text": "Тропари на целование иконы"},
  {"id": "ru-pos-0290", "section": "service", "who": "rubric", "text": "Глас 2:"},
  {"id": "ru-pos-0291", "section": "service", "who": "choir", "text": "Всем Ты покровительствуешь, Благая, / прибегающим с верою под мощную руку Твою: / ибо не имеем в бедах и скорбях мы, грешные, / сгибаемые согрешениями многими, / иного пред Богом постоянного посредничества! / Потому мы припадаем к Тебе, Матерь Бога Всевышнего: / избавь от всякого несчастья рабов Твоих! Глас 2:"},
  {"id": "ru-pos-0292", "section": "service", "who": "choir", "text": "Всех скорбящих Радость, / и обижаемых Заступница, / и алчущих Питательница, / странников утешение ["},
  {"id": "ru-pos-0293", "section": "service", "who": "choir", "text": "и жезл слепым ]"},
  {"id": "ru-pos-0294", "section": "service", "who": "choir", "text": ", / обуреваемых пристанище, немощныных посещение, / изнемогающихх покров и поддержка, / и сиротам помощь, / Матерь Бога Всевышнего – Ты, Пречистая; / поспеши, молимся, для избавления рабов Твоих. Глас 8:"},
  {"id": "ru-pos-0295", "section": "service", "who": "choir", "text": "Владычица, прими прошения рабов Твоих, / и избавь нас от всякого несчастья и печали. Глас 2:"},
  {"id": "ru-pos-0296", "section": "service", "who": "choir", "text": "Всю надежду мою / на Тебя возлагаю, Матерь Божия, / сохрани меня под покровом Твоим."},
  {"id": "ru-pos-0297", "section": "service", "who": "priest", "text": "По молитвам святых отцов наших, Господи Иисусе Христе Боже (наш), помилуй и спаси нас. Аминь. ]"},
];

